git mv src/api/format.ts src/core/money.ts && cat > src/api/format.ts <<'EOF'
export { formatMoney } from "../core/money.ts";
EOF
cat > src/core/loyalty.ts <<'EOF'
import { formatMoney } from "./money.ts";
import type { Customer } from "./price.ts";

export const LOYALTY_MIN_ORDERS = 5;
export const LOYALTY_PERCENT = 10;

export interface LoyaltyResult {
  totalCents: number;
  savedCents: number;
  message: string;
}

export function applyLoyaltyDiscount(customer: Customer, totalCents: number): LoyaltyResult {
  if (customer.orders <= LOYALTY_MIN_ORDERS) {
    return { totalCents, savedCents: 0, message: "" };
  }
  const savedCents = Math.round((totalCents * LOYALTY_PERCENT) / 100);
  return {
    totalCents: totalCents - savedCents,
    savedCents,
    message: `Loyalty discount: you saved ${formatMoney(savedCents)}`,
  };
}
EOF
cat > tests/loyalty.test.ts <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { applyLoyaltyDiscount } from "../src/core/loyalty.ts";

test("more than five orders gets ten percent off", () => {
  assert.deepEqual(applyLoyaltyDiscount({ id: "a", orders: 6 }, 2550), {
    totalCents: 2295,
    savedCents: 255,
    message: "Loyalty discount: you saved $2.55",
  });
});

test("five orders or fewer gets no discount", () => {
  assert.equal(applyLoyaltyDiscount({ id: "a", orders: 5 }, 2550).totalCents, 2550);
});
EOF
node --test tests/ 2>&1 | tail -12; lawcheck check; echo exit $?

